using FluentValidation;using Microsoft.EntityFrameworkCore;using MSA.Contracts;using MSA.EventBus.DependencyInjection;using MSA.EventBusOutbox.Extensions;using MSA.Infrastrucute;using MSA.Infrastrucute.Extensions;using MSA.InventoryService.Application;using MSA.InventoryService.Infrastructure;using MSA.InventoryService.Integration;using OpenTelemetry.Resources;using OpenTelemetry.Trace;
var builder=WebApplication.CreateBuilder(args);var pg=builder.Configuration.GetConnectionString("Postgresql");if(string.IsNullOrWhiteSpace(pg))throw new InvalidOperationException("ConnectionStrings:Postgresql is required.");builder.Services.AddDbContext<InventoryDbContext>(o=>o.UseNpgsql(pg));builder.Services.AddScoped<MSADbContext>(s=>s.GetRequiredService<InventoryDbContext>());builder.Services.AddMediatR(c=>c.RegisterServicesFromAssemblyContaining<AddStockCommand>());builder.Services.AddScoped<IValidator<AddStockCommand>,AddStockValidator>();builder.Services.AddMsaApplicationPipeline();builder.Services.AddStackExchangeRedisCache(o=>o.Configuration=builder.Configuration.GetConnectionString("Redis")??"localhost:6379");builder.Services.AddRabbitMQEventBus(o=>{o.HostName=builder.Configuration["RabbitMQ:Host"]??"localhost";o.UserName=builder.Configuration["RabbitMQ:User"]??"guest";o.Password=builder.Configuration["RabbitMQ:Password"]??"guest";o.QueueName="msa.inventory";});builder.Services.AddOutbox<InventoryDbContext>();builder.Services.AddIntegrationEventHandler<OrderSubmittedIntegrationEvent,OrderSubmittedHandler>();builder.Services.AddIntegrationEventHandler<ReleaseInventoryIntegrationEvent,ReleaseInventoryHandler>();builder.Services.AddIntegrationEventHandler<CommitInventoryIntegrationEvent,CommitInventoryHandler>();builder.Services.AddOpenIddict().AddValidation(o=>{o.SetIssuer(builder.Configuration["Authentication:Issuer"]??"https://localhost:10002/");o.AddAudiences("api");o.UseSystemNetHttp();o.UseAspNetCore();});builder.Services.AddAuthorization(o=>o.AddPolicy("inventory.write",p=>p.RequireAssertion(c=>c.User.Claims.Where(x=>x.Type=="scope").SelectMany(x=>x.Value.Split(' ')).Contains("inventory.write"))));builder.Services.AddHealthChecks();builder.Services.AddProblemDetails();builder.Services.AddOpenTelemetry().WithTracing(t=>t.SetResourceBuilder(ResourceBuilder.CreateDefault().AddService(builder.Environment.ApplicationName)).AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter());var app=builder.Build();if(builder.Configuration.GetValue<bool>("Database:MigrateOnStartup")){await using var scope=app.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Database.MigrateAsync();}app.UseExceptionHandler();app.UseAuthentication();app.UseAuthorization();app.MapHealthChecks("/health");app.MapGet("/api/inventory/{sku}",async(string sku,ISender s,CancellationToken ct)=>{var result=await s.Send(new GetInventoryAvailabilityQuery(sku),ct);return result is null?Results.NotFound():Results.Ok(result);}).RequireAuthorization();app.MapPost("/api/inventory/stock",async(AddStockRequest r,ISender s,CancellationToken ct)=>Results.Ok(new{id=await s.Send(new AddStockCommand(r.Sku,r.Quantity),ct)})).RequireAuthorization("inventory.write");app.Run();
/// <summary>Adds available inventory for a SKU.</summary>
public sealed record AddStockRequest(string Sku,int Quantity);
